WITH a7 AS (SELECT b.mktcode,b.tgtcode,AVG(b.volume) AS volume_avg FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08','2026-04-07','2026-04-03') GROUP BY b.mktcode,b.tgtcode), m5 AS (SELECT b.mktcode,b.tgtcode,MIN(b.volume) AS volume_min FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate IN ('2026-04-14','2026-04-13','2026-04-10','2026-04-09','2026-04-08') GROUP BY b.mktcode,b.tgtcode) SELECT q.mktcode,q.tgtcode,q.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS q INNER JOIN a7 ON a7.mktcode=q.mktcode AND a7.tgtcode=q.tgtcode INNER JOIN m5 ON m5.mktcode=q.mktcode AND m5.tgtcode=q.tgtcode WHERE q.bizdate='2026-04-14' AND a7.volume_avg=m5.volume_min AND ((q.lastPx-q.preClosePx)*100.0/NULLIF(q.preClosePx,0))>2;
